from collections import deque


def largestPeacefulGroup(n, dislikes):
    adj = [[] for _ in range(n)]
    for a, b in dislikes:
        adj[a].append(b)
        adj[b].append(a)
    color = [-1] * n
    for s in range(n):
        if color[s] != -1:
            continue
        color[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    queue.append(v)
    left = [v for v in range(n) if color[v] == 0]
    match_left = [-1] * n
    match_right = [-1] * n
    matching = 0
    while True:
        # BFS layers from all free left nodes along alternating paths
        layer = {}
        queue = deque()
        for u in left:
            if match_left[u] == -1:
                layer[u] = 0
                queue.append(u)
        found = False
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                w = match_right[v]
                if w == -1:
                    found = True
                elif w not in layer:
                    layer[w] = layer[u] + 1
                    queue.append(w)
        if not found:
            break
        ptr = [0] * n
        for s in left:
            if match_left[s] != -1:
                continue
            stack = [s]
            chosen = []
            while stack:
                u = stack[-1]
                if ptr[u] < len(adj[u]):
                    v = adj[u][ptr[u]]
                    ptr[u] += 1
                    w = match_right[v]
                    if w == -1:
                        chosen.append(v)
                        for x, y in zip(stack, chosen):
                            match_left[x] = y
                            match_right[y] = x
                        matching += 1
                        break
                    if layer.get(w) == layer[u] + 1:
                        chosen.append(v)
                        stack.append(w)
                else:
                    stack.pop()
                    if chosen:
                        chosen.pop()
    return n - matching
